// ResourceIDAnnotation is used to uniquely identify the resource during round trip
// to and from a function execution. This annotation is meant to be consumed by
// kpt during round trip and should be deleted after that
const ResourceIDAnnotation = "internal.config.kubernetes.io/kpt-resource-id"

// SaveResults saves results gathered from running the pipeline at specified dir in the input FileSystem.
func SaveResults(fsys filesys.FileSystem, resultsDir string, fnResults *fnresultv1.ResultList) (string, error) {
	if resultsDir == "" {
		return "", nil
	}
	filePath := filepath.Join(resultsDir, "results.yaml")
	out := &bytes.Buffer{}

	// use kyaml encoder to ensure consistent indentation
	e := yaml.NewEncoderWithOptions(out, &yaml.EncoderOptions{SeqIndent: yaml.WideSequenceStyle})
	err := e.Encode(fnResults)
	if err != nil {
		return "", err
	}

	err = fsys.WriteFile(filePath, out.Bytes())
	if err != nil {
		return "", err
	}

	return filePath, nil
}

// MergeWithInput merges the transformed output with input resources
// input: all input resources, selectedInput: selected input resources
// output: output resources as the result of function on selectedInput resources
// for input: A,B,C,D; selectedInput: A,B; output: A,E(A transformed, B Deleted, E Added)
// the result should be A,C,D,E
// resources are identified by kpt-resource-id annotation
func MergeWithInput(output, selectedInput, input []*yaml.RNode) []*yaml.RNode {
	var result []*yaml.RNode
	for i := range input {
		presentInSelectedInput := presentIn(input[i], selectedInput)
		presentInOutput := presentIn(input[i], output)
		if !presentInSelectedInput {
			// this resource is untouched
			result = append(result, input[i])
			continue
		}

		if presentInOutput {
			// this resource modified by function, so replace it from the output
			result = append(result, nodeWithResourceID(input[i].GetAnnotations()[ResourceIDAnnotation], output))
		}
		// if presentInSelectedInput and !presentInOutput the resource is deleted, so ignore it
	}

	// add function generated resources to the result

		selectedResources, err := fnruntime.SelectInput(input, function.Selectors, function.Exclusions, &fnruntime.SelectionContext{RootPackagePath: hctx.root.pkg.UniquePath})
		if err != nil {
			return err
		}
		var validator *fnruntime.FunctionRunner
		displayResourceCount := len(function.Selectors) > 0 || len(function.Exclusions) > 0
		if function.Exec != "" && !hctx.runnerOptions.AllowExec {
			hctx.validationSteps = append(hctx.validationSteps, preExecFailureStep(function, errAllowedExecNotSpecified))
			return errAllowedExecNotSpecified
		}
		opts := hctx.runnerOptions
		opts.SetPkgPathAnnotation = true
		opts.DisplayResourceCount = displayResourceCount
		validator, err = fnruntime.NewRunner(ctx, hctx.fileSystem, &function, pn.pkg.UniquePath, hctx.fnResults, opts, hctx.runtime)
		if err != nil {
			hctx.validationSteps = append(hctx.validationSteps, preExecFailureStep(function, err))
			return err
		}

		if err := pn.refreshFnConfig(validator, input, function.ConfigPath); err != nil {
			return err
		}

		if _, err = validator.Filter(cloneResources(selectedResources)); err != nil {
			hctx.validationSteps = append(hctx.validationSteps, captureStepResult(function, hctx.fnResults, resultCountBeforeExec, err))
			return err
		}
		hctx.executedFunctionCnt++
		hctx.validationSteps = append(hctx.validationSteps, captureStepResult(function, hctx.fnResults, resultCountBeforeExec, nil))
	}
	return nil
}

func cloneResources(input []*yaml.RNode) (output []*yaml.RNode) {
	for _, resource := range input {
		output = append(output, resource.Copy())
	}
	return
}

// refreshFnConfig updates the runner's functionConfig from the in-memory input
// to pick up any mutations applied earlier in the pipeline.
func (pn *pkgNode) refreshFnConfig(runner *fnruntime.FunctionRunner, input []*yaml.RNode, configPath string) error {
	if configPath == "" {
		return nil
	}
	for _, r := range input {
		pkgPath, err := pkg.GetPkgPathAnnotation(r)
		if err != nil {
			return err
		}
		currPath, _, err := kioutil.GetFileAnnotations(r)
		if err != nil {
			return err
		}
		if pkgPath == pn.pkg.UniquePath.String() && currPath == configPath {
			runner.SetFnConfig(r)
			break
		}
	}
	return nil
}

// clearAnnotationsOnMutFailure removes annotations that are added during mutation when mutation fails.
func clearAnnotationsOnMutFailure(input []*yaml.RNode) {
	annotations := []string{
		"config.k8s.io/id",
		"internal.config.kubernetes.io/annotations-migration-resource-id",
		"internal.config.kubernetes.io/id",
		fnruntime.ResourceIDAnnotation,
	}
	for _, r := range input {
		for _, annotation := range annotations {
			_ = r.PipeE(yaml.ClearAnnotation(annotation))
		}
	}
}

